create table if not exists public.ce_products(product_id text not null,version text not null,state text not null check(state in('DRAFT','ACTIVE','DEPRECATED','BLOCKED')),definition jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),primary key(product_id,version));alter table public.ce_products enable row level security;revoke all on public.ce_products from public,anon,authenticated;grant select,insert,update,delete on public.ce_products to service_role;